CREATE TABLE previews(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,job_id TEXT NOT NULL REFERENCES build_jobs(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('created','loading','ready','runtime_error','timed_out','stopped','expired')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,receipt_origin TEXT NOT NULL DEFAULT 'browser-unverified');
CREATE TABLE preview_events(preview_id TEXT NOT NULL REFERENCES previews(id) ON DELETE CASCADE,id INTEGER PRIMARY KEY AUTOINCREMENT,status TEXT NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
